package br.com.agendou.catalog;
import br.com.agendou.billing.SubscriptionService;
import br.com.agendou.tenancy.*;
import br.com.agendou.web.CorrelationIdFilter;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.time.Instant;
import java.util.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController @RequestMapping("/api/v1/admin/customers")
public class CustomerAdminController {
 private final JdbcTemplate jdbc;private final TenantSessionConfigurer tenants;private final SubscriptionService subscriptions;private final BookingService bookings;
 public CustomerAdminController(JdbcTemplate jdbc,TenantSessionConfigurer tenants,SubscriptionService subscriptions,BookingService bookings){this.jdbc=jdbc;this.tenants=tenants;this.subscriptions=subscriptions;this.bookings=bookings;}
 private void bind(boolean write){tenants.applyCurrentTenant();if(write){jdbc.queryForObject("SELECT id FROM tenants WHERE id=? FOR UPDATE",UUID.class,TenantContext.require());subscriptions.requireOperational(TenantContext.require());}}
 private ResponseEntity<?> response(Object body){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(body);}
 private Map<String,Object> customer(UUID id){var rows=jdbc.query("SELECT id,name,coalesce(email,''),phone,version,EXISTS(SELECT 1 FROM bookings b WHERE b.tenant_id=c.tenant_id AND b.customer_id=c.id) FROM customers c WHERE tenant_id=? AND id=?",(r,n)->Map.<String,Object>of("id",r.getObject(1,UUID.class),"name",r.getString(2),"email",r.getString(3),"phone",r.getString(4),"version",r.getInt(5),"emailLocked",r.getBoolean(6)),TenantContext.require(),id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Cliente não encontrado.");return rows.getFirst();}
 @GetMapping @Transactional(readOnly=true) public ResponseEntity<?> list(@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int offset){bind(false);if(search.length()>100||offset<0||offset>100000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Busca inválida.");var ids=jdbc.query("SELECT id FROM customers WHERE tenant_id=? AND (name ILIKE ? OR email ILIKE ? OR phone ILIKE ?) ORDER BY lower(name),id LIMIT 51 OFFSET ?",(r,n)->r.getObject(1,UUID.class),TenantContext.require(),"%"+search.trim()+"%","%"+search.trim()+"%","%"+search.trim()+"%",offset);return response(Map.of("items",ids.stream().limit(50).map(this::customer).toList(),"hasMore",ids.size()>50));}
 @GetMapping("/{id}") @Transactional public ResponseEntity<?> detail(@PathVariable UUID id,@RequestParam(defaultValue="0") int offset){bind(false);if(offset<0||offset>100000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Página inválida.");var c=customer(id);jdbc.queryForObject("SELECT id FROM tenants WHERE id=? FOR UPDATE",UUID.class,TenantContext.require());bookings.expireCurrent();var history=jdbc.query("SELECT id,status,starts_at,timezone,service_snapshot->>'name',price_cents FROM bookings WHERE tenant_id=? AND customer_id=? ORDER BY starts_at DESC,id DESC LIMIT 21 OFFSET ?",(r,n)->Map.of("id",r.getObject(1,UUID.class),"status",r.getString(2),"start",r.getTimestamp(3).toInstant(),"timezone",r.getString(4),"serviceName",r.getString(5),"priceCents",r.getLong(6)),TenantContext.require(),id,offset);return response(Map.of("customer",c,"bookings",history.stream().limit(20).toList(),"hasMore",history.size()>20));}
 public record Edit(@NotBlank @Size(min=2,max=100) String name,@NotNull @Email @Size(max=254) String email,@NotNull @Pattern(regexp="^$|[+0-9 ()-]{8,25}") String phone,@NotNull @Min(0) Integer version){@Override public String toString(){return "CustomerEdit[redacted]";}}
 @PostMapping @Transactional public ResponseEntity<?> create(@Valid @RequestBody Edit input,HttpServletRequest request){bind(true);String name=input.name().trim(),email=input.email().trim().toLowerCase(Locale.ROOT);if(name.length()<2)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Informe o nome completo.");String phone=input.phone().trim();if(email.isEmpty()){name=CustomerContact.name(name);if(!name.contains(" "))throw conflict("Informe nome e sobrenome.");phone=CustomerContact.phone(phone);}var existing=jdbc.query("SELECT id FROM customers WHERE tenant_id=? AND (email=? OR (email IS NULL AND phone=? AND contact_name_key=?))",(r,n)->r.getObject(1,UUID.class),TenantContext.require(),email,email.isEmpty()?phone:"",CustomerContact.key(name));if(!existing.isEmpty())return response(customer(existing.getFirst()));UUID id=UUID.randomUUID();jdbc.update("INSERT INTO customers(id,tenant_id,name,email,phone,contact_name_key) VALUES (?,?,?,?,?,?)",id,TenantContext.require(),name,email.isEmpty()?null:email,phone,CustomerContact.key(name));audit(id,0,"CREATED",request);return response(customer(id));}
 @PutMapping("/{id}") @Transactional public ResponseEntity<?> update(@PathVariable UUID id,@Valid @RequestBody Edit input,HttpServletRequest request){bind(true);var old=customer(id);String name=input.name().trim(),email=input.email().trim().toLowerCase(Locale.ROOT);if(name.length()<2)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Informe o nome completo.");if(((Number)old.get("version")).intValue()!=input.version())throw conflict("Cadastro alterado em outra janela. Atualize antes de salvar.");if(Boolean.TRUE.equals(old.get("emailLocked"))&&!old.get("email").equals(email))throw conflict("O email identifica o acesso ao histórico e não pode ser alterado neste cadastro após uma reserva.");if(jdbc.queryForObject("SELECT count(*) FROM customers WHERE tenant_id=? AND email=? AND id<>?",Long.class,TenantContext.require(),email,id)>0)throw conflict("Já existe cliente com esse email. Os históricos não foram mesclados.");String phone=input.phone().trim();if(email.isEmpty()){name=CustomerContact.name(name);if(!name.contains(" "))throw conflict("Informe nome e sobrenome.");phone=CustomerContact.phone(phone);}jdbc.update("UPDATE customers SET name=?,email=?,phone=?,contact_name_key=?,version=version+1 WHERE tenant_id=? AND id=?",name,email.isEmpty()?null:email,phone,CustomerContact.key(name),TenantContext.require(),id);audit(id,input.version()+1,"UPDATED",request);return response(customer(id));}
 private void audit(UUID id,int version,String type,HttpServletRequest request){jdbc.update("INSERT INTO customer_changes(id,tenant_id,customer_id,recorded_by,version,event_type,correlation_id) VALUES (?,?,?,?,?,?,?)",UUID.randomUUID(),TenantContext.require(),id,UUID.fromString(request.getUserPrincipal().getName()),version,type,CorrelationIdFilter.id(request));}
 @GetMapping("/{id}/booking-quote") @Transactional(readOnly=true) public ResponseEntity<?> quote(@PathVariable UUID id,@RequestParam UUID serviceId)throws Exception{bind(false);customer(id);return response(bookings.assistedQuote(serviceId));}
 public record Assisted(@NotNull UUID serviceId,@NotNull Instant start,@NotNull UUID requestKey,@NotBlank @Size(max=100) String quote,@NotNull @AssertTrue Boolean confirmed){}
 @PostMapping("/{id}/bookings") @Transactional(rollbackFor=Exception.class) public ResponseEntity<?> reserve(@PathVariable UUID id,@Valid @RequestBody Assisted input,HttpServletRequest request)throws Exception{bind(true);var session=request.getSession();String marker="assisted-code:"+input.requestKey();String code=(String)session.getAttribute(marker);if(code==null){code=CustomerContact.code();session.setAttribute(marker,code);}return response(bookings.createAssisted(id,input.serviceId(),input.start(),input.requestKey(),input.quote(),UUID.fromString(request.getUserPrincipal().getName()),code));}
 private static ResponseStatusException conflict(String message){return new ResponseStatusException(HttpStatus.CONFLICT,message);}
}
